//! Streaming offline evaluation of the application causal path. Collector
//! statistics are not inference state and are never fed back to the model.
use mabi_meter_core::{capture_file,health::{Accounting,Health},identity::EntityKey,replay::Replay,Result};
use serde_json::{json,Value};
use std::{collections::BTreeMap,path::Path,time::Instant};
#[derive(Default)]
struct Tally{intervals:u64,loss:u128,explicit:u128,inferred:u128,unassigned:u128,mismatch_count:u64,mismatch_loss:u128,methods:BTreeMap<&'static str,(u64,u128)>}
impl Tally{
    fn add(&mut self,a:&Accounting){self.intervals+=1;self.loss+=a.loss as u128;self.explicit+=a.explicit as u128;self.unassigned+=a.unassigned as u128;let n=a.allocations.iter().map(|e|e.amount as u128).sum::<u128>();self.inferred+=n;if a.explicit_mismatch{self.mismatch_count+=1;self.mismatch_loss+=a.loss as u128;}let method=self.methods.entry(a.reason).or_default();method.0+=1;method.1+=n;}
    fn json(&self)->Value{json!({"intervals":self.intervals,"loss":self.loss.to_string(),"matched_explicit_impact":self.explicit.to_string(),"inferred":self.inferred.to_string(),"resource_or_unresolved_loss":self.unassigned.to_string(),"explicit_mismatch_count":self.mismatch_count,"explicit_mismatch_loss":self.mismatch_loss.to_string(),"methods":self.methods.iter().map(|(method,(count,amount))|json!({"method":method,"intervals":count,"inferred_amount":amount.to_string()})).collect::<Vec<_>>()})}
}
struct Latency{bins:[u64;64],count:u64,sum:u128,max:u64}
impl Default for Latency{fn default()->Self{Self{bins:[0;64],count:0,sum:0,max:0}}}
impl Latency{
    fn add(&mut self,ns:u64){self.count+=1;self.sum+=ns as u128;self.max=self.max.max(ns);let bin=63-ns.max(1).leading_zeros() as usize;self.bins[bin]+=1;}
    fn quantile_upper(&self,numerator:u64,denominator:u64)->Option<u64>{if self.count==0{return None;}let rank=(self.count as u128*numerator as u128).div_ceil(denominator as u128) as u64;let mut sum=0;for (bin,count) in self.bins.iter().enumerate(){sum+=count;if sum>=rank{return Some(if bin==63{u64::MAX}else{(1u64<<(bin+1))-1});}}None}
    fn json(&self)->Value{json!({"scope":"time inside Replay.feed only; collector/file parsing excluded; not network or decision latency","count":self.count,"sum_ns":self.sum.to_string(),"p50_upper_ns":self.quantile_upper(50,100),"p95_upper_ns":self.quantile_upper(95,100),"p99_upper_ns":self.quantile_upper(99,100),"max_ns":self.max,"log2_ns_histogram":self.bins.to_vec()})}
}
#[derive(Default)]
struct Heldout{records:u64,raw:u128,positive_records:u64,positive_impact:u128,zero:u64,unsupported:u64,noncanonical_source_prefix:u64}
#[derive(Default)]
struct Collector{seen:u64,max_batch:u64,wire_seen:u64,inputs:u64,sampled_dependency_peak:usize,sampled_total_peak:usize,all:Tally,targets:BTreeMap<EntityKey,Tally>,allocations:BTreeMap<EntityKey,BTreeMap<EntityKey,u128>>,allocation_pairs:usize,raw_pairs:usize,raw_sources:BTreeMap<(u64,u64),BTreeMap<u64,(u64,u128,u64)>>,historical_cases:[Option<Value>;13],withhold_actor:Option<u32>,heldout:BTreeMap<u64,Heldout>}
const HISTORICAL_HP_FRAMES:[u64;13]=[730165,848182,931553,933676,934775,936824,959104,962904,985609,986366,986847,988114,1006794];
fn key_json(k:EntityKey)->Value{json!([k.process,k.binding,k.actor,k.generation])}
impl Collector{
    fn observe(&mut self,r:&Replay)->Result<()>{
        self.inputs+=1;
        if self.inputs%128==0{self.sample_resources(r);}
        self.health(&r.health)?;
        let total=r.damage_wire.evicted+r.damage_wire.retained() as u64;let new=total.checked_sub(self.wire_seen).ok_or("field append count moved backwards")?;
        if new>r.damage_wire.retained() as u64{return Err("field ring overflow inside one input; raw source census incomplete".into());}
        let skip=r.damage_wire.retained()-new as usize;
        for o in r.damage_wire.observations().skip(skip){let f=o.fields;let target=(o.at.context,f.target_prefix);if !self.raw_sources.contains_key(&target) && self.raw_sources.len()==16384{return Err("offline target census capacity reached".into());}let sources=self.raw_sources.entry(target).or_default();if !sources.contains_key(&f.source_prefix) && sources.len()==4096{return Err("offline source census capacity reached".into());}if !sources.contains_key(&f.source_prefix){if self.raw_pairs==65536{return Err("offline raw source-pair capacity reached".into());}self.raw_pairs+=1;}let source=sources.entry(f.source_prefix).or_default();source.0+=1;if f.raw_amount<=1_000_000_000_000{source.1+=f.raw_amount as u128;}source.2+=u64::from(!f.legacy_supported());
            if self.withhold_actor.is_some_and(|actor|f.source_prefix as u32==actor) && f.legacy_supported(){if !self.heldout.contains_key(&f.target_prefix) && self.heldout.len()==16384{return Err("heldout target census capacity reached".into());}let held=self.heldout.entry(f.target_prefix).or_default();held.records+=1;held.raw+=f.raw_amount as u128;held.noncanonical_source_prefix+=u64::from(f.source_prefix>u32::MAX as u64);match f.hp_impact_candidate(){Some(0)=>held.zero+=1,Some(n)=>{held.positive_records+=1;held.positive_impact+=n as u128;},None=>held.unsupported+=1}}
        }
        self.wire_seen=total;Ok(())
    }
    fn sample_resources(&mut self,r:&Replay){let extra=r.assignment_storage();let dependencies=r.combat.assignment_owned_bytes()+r.timeline.assignment_owned_bytes()+r.damage_wire.owned_bytes()+extra["pending_skill_owned_bytes"].as_u64().unwrap_or(0) as usize+extra["hp_publication_chain_conservative_bytes"].as_u64().unwrap_or(0) as usize;self.sampled_dependency_peak=self.sampled_dependency_peak.max(dependencies);let health=r.health.resource_summary();let resident=health["conservative_resident_bytes"].as_u64().unwrap_or(0) as usize;let scratch=health["scratch_ceiling_bytes"].as_u64().unwrap_or(0) as usize;self.sampled_total_peak=self.sampled_total_peak.max(dependencies+resident+scratch);}
    fn health(&mut self,h:&Health)->Result<()>{let total=h.audit_evictions+h.audit.len() as u64;let new=total.checked_sub(self.seen).ok_or("audit append count moved backwards")?;if new>h.audit.len() as u64{return Err("audit overflow inside one input; streaming tally incomplete".into());}self.max_batch=self.max_batch.max(new);for a in h.audit.iter().rev().take(new as usize){self.all.add(a);if a.target.actor==4425809{if let Some(i)=HISTORICAL_HP_FRAMES.iter().position(|f|*f==a.at.frame){self.historical_cases[i]=Some(json!({"hp_frame":a.at.frame,"interval":a.id,"loss":a.loss,"matched_explicit_impact":a.explicit,"inferred":a.allocations.iter().map(|e|e.amount).sum::<u64>(),"unresolved_or_resource_loss":a.unassigned,"method":a.reason,"evidence_frames":a.evidence,"allocations":a.allocations.iter().map(|e|json!({"source":key_json(e.source),"amount":e.amount,"frames":e.frames,"skill":e.skill,"method":e.method})).collect::<Vec<_>>()}));}}if !self.targets.contains_key(&a.target) && self.targets.len()==16384{return Err("offline accounting census capacity reached".into());}self.targets.entry(a.target).or_default().add(a);for e in &a.allocations{let sources=self.allocations.entry(a.target).or_default();if !sources.contains_key(&e.source){if self.allocation_pairs==65536{return Err("offline allocation census capacity reached".into());}self.allocation_pairs+=1;}*sources.entry(e.source).or_default()+=e.amount as u128;}}self.seen=total;Ok(())}
    fn raw_json(&self)->Value{let mut targets:Vec<_>=self.raw_sources.iter().collect();targets.sort_by_key(|(_,sources)|std::cmp::Reverse(sources.values().map(|v|v.1).sum::<u128>()));json!({"scope":"full known-prefix raw sources by directional context/target before names, owner grouping or semantic acceptance; source fields do not prove player identity","target_contexts":targets.len(),"maximum_sources_per_target_context":targets.iter().map(|(_,s)|s.len()).max().unwrap_or(0),"top_targets":targets.into_iter().take(32).map(|((context,target),sources)|json!({"context":context,"target_prefix":target,"source_count":sources.len(),"sources":sources.iter().map(|(source,(count,amount,rejected))|json!({"source_prefix":source,"records":count,"raw_amount_below_sanity_ceiling":amount.to_string(),"outside_legacy_gate":rejected})).collect::<Vec<_>>()})).collect::<Vec<_>>()})}
    fn heldout_json(&self,_r:&Replay)->Value{Value::Null}
}
fn main(){if let Err(e)=run(){eprintln!("{e}");std::process::exit(1);}}
fn run()->Result<()>{
    let mut paths=Vec::new();let mut no_clock=false;let mut retention_ms=None;let mut locality_ms=None;let withhold_actor:Option<u32>=None;let mut args=std::env::args().skip(1);
    while let Some(arg)=args.next(){match arg.as_str(){"--no-clock"=>no_clock=true,"--retention-ms"=>retention_ms=Some(args.next().ok_or("missing retention")?.parse::<u64>().map_err(|e|e.to_string())?),"--locality-ms"=>locality_ms=Some(args.next().ok_or("missing locality")?.parse::<u64>().map_err(|e|e.to_string())?),"--withhold-actor"=>return Err("withholding is not a production replay feature; transform offline input fixtures instead".into()),_=>paths.push(arg)}}
    if paths.is_empty(){return Err("usage: evaluate_causal [--retention-ms N] [--locality-ms N] CAPTURE...".into());}
    for input in paths{let start=Instant::now();let mut r=Replay::new(false);let mut collector=Collector::default();let mut latency=Latency::default();r.use_clock_bounds=!no_clock;collector.withhold_actor=withhold_actor;
        if let Some(ms)=retention_ms{r.health.retention_ns=ms.checked_mul(1_000_000).ok_or("retention overflow")?;}
        if let Some(ms)=locality_ms{r.health.local_capture_ns=ms.checked_mul(1_000_000).ok_or("locality overflow")?;}
        if r.health.retention_ns==0 || r.health.local_capture_ns==0 || r.health.local_capture_ns>r.health.retention_ns{return Err("require 0 < locality <= retention".into());}
        capture_file::read(Path::new(&input),None,|i|{let before=Instant::now();r.feed(i)?;latency.add(before.elapsed().as_nanos().min(u64::MAX as u128) as u64);collector.observe(&r)})?;
        let before=Instant::now();r.finish();let finish_ns=before.elapsed().as_nanos().min(u64::MAX as u128) as u64;collector.observe(&r)?;
        if let Some(error)=r.semantic_error.clone(){return Err(error);}
        if collector.all.loss!=r.health.loss || collector.all.explicit!=r.health.explicit{return Err("streaming interval tally differs from Health lifetime totals".into());}
        if r.health.loss!=r.health.explicit+r.health.allocated+r.health.unassigned{return Err("HP budget dispositions do not conserve detected loss".into());}
        let obligations=r.health.attribution.audit();
        if obligations["invariant"]!=true || obligations["by_origin"]["explicit"]["invariant"]!=true || obligations["by_origin"]["inferred"]["invariant"]!=true{return Err("packet obligation conservation failed".into());}
        if r.numeric.detected!=r.health.loss{return Err(format!("numeric detected {} differs from accounted HP {}",r.numeric.detected,r.health.loss));}
        if r.health.attribution.published_inferred!=r.meter.session.estimated_total.damage || r.health.attribution.published_explicit!=r.meter.session.total.damage{return Err("acknowledged credit differs from meter authoritative amounts".into());}
        let resources=r.health.resource_summary();collector.sample_resources(&r);
        let dependencies=json!({"combat_end_bytes":r.combat.assignment_owned_bytes(),"timeline_end_bytes":r.timeline.assignment_owned_bytes(),"damage_field_ring_bytes":r.damage_wire.owned_bytes(),"sampled_peak_sum_bytes":collector.sampled_dependency_peak,"sampled_total_with_health_and_scratch_peak_bytes":collector.sampled_total_peak,"sampling":"every128inputs plusEOF; sampled peak is not an exact transient maximum; Health tracks own highwater separately","excluded":"existing independent diagnostic frame_history, transport buffers, identity registry and downstream meter aggregates; evaluator collection is offline only"});
        println!("{}",json!({"attribution_obligations":obligations,"numeric_observations":r.numeric.audit(),"input":input,"scope":"integrated default file replay unless offline withholding_ablation is present; overlapping recordings are not independent accuracy replications","withholding_ablation":collector.heldout_json(&r),"candidate_clock_annotations":!no_clock,"storage_contract":r.assignment_storage(),"explicit_source_roles":{"counts":r.explicit_origins,"examples":r.explicit_origin_examples},"frames":r.frames,"segments":r.segments,"explicit_records":r.meter.session.total.hits,"raw_explicit_amount":r.meter.session.total.damage.to_string(),"meter_inferred":r.meter.session.estimated_total.damage.to_string(),"all":collector.all.json(),"outcomes":r.health.outcomes,"audit_rows_seen":collector.seen,"audit_rows_evicted":r.health.audit_evictions,"max_rows_closed_per_input":collector.max_batch,"historical_interleaving_cases":{"target":4425809,"scope":"fixed13previous8messageexclusions, regressiononly; frame numbering must match current native framing","frames":HISTORICAL_HP_FRAMES,"matched":collector.historical_cases.iter().filter(|c|c.is_some()).count(),"cases":collector.historical_cases},"targets":collector.targets.iter().map(|(target,tally)|json!({"target":key_json(*target),"tally":tally.json(),"sources":collector.allocations.get(target).into_iter().flat_map(|sources|sources.iter()).map(|(source,amount)|json!({"source":key_json(*source),"amount":amount.to_string()})).collect::<Vec<_>>()})).collect::<Vec<_>>(),"raw_explicit_sources":collector.raw_json(),"damage_fields":r.damage_wire.summary(),"protected_hp_decoded":r.diagnostics.0.get("protected_hp_decoded").copied().unwrap_or(0),"model":r.combat.damage_model.summary(),"resources":resources,"assignment_dependencies":dependencies,"service_latency":latency.json(),"finish_service_ns":finish_ns,"elapsed_seconds":start.elapsed().as_secs_f64(),"diagnostics":r.diagnostics.0,"release":"blocked"}));
    }Ok(())
}
